/** API config for a chart zoom interaction */
export interface ChartZoomConfig {
    /** Enables a specific zoom interaction on the chart. */
    enabled?: boolean;
}
/** Type of event when performing a zoom action that triggers a change in the domain */
export type ZoomChangeType = 'reset' | 'zoom-x' | 'panning' | 'zoom-in' | 'zoom-out';
/** Different chart modes for zooming or interacting with the chart */
export declare const zoomModeOptions: readonly ["explore", "panning"];
export type ZoomMode = (typeof zoomModeOptions)[number];
export type DownloadData = 'download';
/** All charts interactions and modes there are */
export type ChartInteractionModes = ZoomMode | ZoomChangeType | DownloadData;
/** Different chart modes actionable by keyboard */
export type ZoomKeyboardMode = Extract<ChartInteractionModes, 'panning' | 'explore'>;
/** Zoom in and Zoom out toolbar interactions*/
export type ZoomInZoomOut = Extract<ChartInteractionModes, 'zoom-in' | 'zoom-out'>;
